    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'در میز اطلاعات دانشگاه، برنامه دو روزت را بگو: جلسه دوشنبه صبح و کلاس سه شنبه بعدازظهر.','در این موقعیت، پاسخ مناسب را با صدا بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"در میز اطلاعات دانشگاه، برنامه دو روزت را بگو: جلسه دوشنبه صبح و کلاس سه شنبه بعدازظهر.","accepted_intents":["My meeting is on Monday morning, and my class is on Tuesday afternoon.","I have a meeting Monday morning and a class Tuesday afternoon."],"evaluation":"stt","input":"speech","scored":true,"independent":true}' AS JSON),JSON_OBJECT('phase','transfer','typing',FALSE,'novelScenario',TRUE,'masteryCheck',TRUE));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'مایا باید زمان پایان کلاس را ثبت کند؛ بگو کلاس سه شنبه ساعت دو تمام می‌شود.','در این موقعیت، پاسخ مناسب را با صدا بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"مایا باید زمان پایان کلاس را ثبت کند؛ بگو کلاس سه شنبه ساعت دو تمام می‌شود.","accepted_intents":["The Tuesday class finishes at two.","My class is on Tuesday and it finishes at two."],"evaluation":"stt","input":"speech","scored":true,"independent":true}' AS JSON),JSON_OBJECT('phase','transfer','typing',FALSE,'novelScenario',TRUE,'masteryCheck',TRUE));
  ELSEIF v_count=1 THEN
    SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=5;
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>42 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'en-fa-a1-series-0005' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<12 OR COUNT(a.id)>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_en_series_005()$$
DROP PROCEDURE IF EXISTS import_nova_en_series_005$$
